import { useState } from "react";
import { Wizard } from "./Wizard.jsx";

export default function App() {
  const [inscrito, setInscrito] = useState(null);

  return (
    <main style={{ maxWidth: 420, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Inscripción al taller de React</h1>
      {inscrito ? (
        <p>
          ¡Listo, {inscrito.nombre}! Quedaste inscrito desde {inscrito.escuela}.
        </p>
      ) : (
        <Wizard onFinalizar={setInscrito} />
      )}
    </main>
  );
}
